"""Task5 dual-model UART7 single-file build for OpenMV N6.

Target: OpenMV v5.0.0 / MicroPython v1.28.0-49 / OpenMV N6.
UART7: P14=TX, P13=RX, 115200 8N1.
1 kHz: white-frame PCA/KNN v2; 10 kHz: existing trace PCA/KNN.
"""

