# OpenMV N6 UART7: P14=TX, P13=RX.
UART_ID = 7
UART_TX_PIN = "P14"
UART_RX_PIN = "P13"
UART_BAUDRATE = 115200
UART_RX_BUFFER_BYTES = 512
UART_TX_BUFFER_BYTES = 512

# Coarse recognition must finish before the STM32's 5 s timeout.
COARSE_TIMEOUT_MS = 4000
COARSE_WINDOW_FRAMES = 12
COARSE_MIN_SAMPLES = 8
COARSE_CLUSTER_RADIUS = 0.3
COARSE_MIN_CONFIDENCE = 50

# Until the second-stage Lissajous dataset/model is available, DDS_TEST
# direction is compared with the accepted coarse estimate. This validates
# the complete UART state machine but is not the final visual fine search.
DDS_NUMERIC_FALLBACK = True

CONSOLE_DEBUG = False

