# =========================== MODEL MAP ============================

MODEL_KIND_TRACE = 0
MODEL_KIND_WHITE_FRAME = 1

MODEL_1K_SPEC = (
    MODEL_KIND_WHITE_FRAME,
    M1_FEATURE_SIDE,
    M1_FEATURE_COUNT,
    M1_COMPONENTS,
    M1_EXEMPLARS,
    M1_PROJECTION_QUANTIZATION,
    M1_SCREEN_DARK_MAX,
    M1_SCREEN_MARGIN_X1000,
    M1_SCREEN_TRACK_HOLD_FRAMES,
    M1_WEIGHT_SCALES,
    M1_BIASES,
    M1_WEIGHT_B64_PARTS,
    M1_EXEMPLAR_B64_PARTS,
    M1_LABEL_B64_PARTS,
)

