# ======================== PCA/KNN CLASSIFIER ======================

class RatioResult:
    def __init__(self):
        self.found = False
        self.accepted = False
        self.rect = None
        self.patch_rect = None
        self.frame_ratio = 0.0
        self.ratio = 0.0
        self.estimated_frequency_hz = 0
        self.confidence = 0
        self.stable_frames = 0
        self.predictions = ()
        self.nearest_distance = 0.0
        self.second_distance = 0.0
        self.analysis_ms = 0
        self.method = "PCA-KNN"
        self.tracked_rect = False
        self.failure_reason = ""

    def clear(self):
        self.found = False
        self.accepted = False
        self.rect = None
        self.patch_rect = None
        self.frame_ratio = 0.0
        self.ratio = 0.0
        self.estimated_frequency_hz = 0
        self.confidence = 0
        self.stable_frames = 0
        self.predictions = ()
        self.nearest_distance = 0.0
        self.second_distance = 0.0
        self.analysis_ms = 0
        self.tracked_rect = False
        self.failure_reason = ""
        return self


def _clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value


def _ticks_ms():
    return time.ticks_ms()


def _ticks_diff(new, old):
    return time.ticks_diff(new, old)


def _decode_model_data(encoded):
    if isinstance(encoded, tuple):
        decoded = []
        for part in encoded:
            decoded.append(binascii.a2b_base64(part))
        return b"".join(decoded)
    return binascii.a2b_base64(encoded)


class PcaRatioClassifier:
    """One classifier implementation backed by a selected embedded model.

    model_spec fields:
      model_kind, feature_side, feature_count, components, exemplars,
      projection_quantization, locator_a, locator_b, locator_c,
      weight_scales, biases, weight_data, exemplar_data, label_data.

    The 1 kHz model uses a dark-screen ROI isolated by a white frame.
    The 10 kHz model retains the original green-trace locator.
    """

    def __init__(self, model_spec, fusion_frames=3, accept_confidence=45):
        (
            self.model_kind,
            self.feature_side,
            self.feature_count,
            self.components,
            self.exemplar_count,
            self.projection_quantization,
            locator_a,
            locator_b,
            locator_c,
            weight_scales,
            biases,
            weight_data,
            exemplar_data,
            label_data,
        ) = model_spec

        if self.model_kind == MODEL_KIND_WHITE_FRAME:
            self.screen_dark_max = locator_a
            self.screen_margin_x1000 = locator_b
            self.screen_hold_frames = locator_c
            self.green_minus_red_min = 0
            self.green_minus_blue_min = 0
            self.mask_dilation = 0
        elif self.model_kind == MODEL_KIND_TRACE:
            self.screen_dark_max = 0
            self.screen_margin_x1000 = 0
            self.screen_hold_frames = 0
            self.green_minus_red_min = locator_a
            self.green_minus_blue_min = locator_b
            self.mask_dilation = locator_c
        else:
            raise ValueError("unknown model kind")

        self.fusion_frames = fusion_frames
        self.accept_confidence = accept_confidence
        self.result = RatioResult()
        if self.model_kind == MODEL_KIND_WHITE_FRAME:
            self.result.method = "WHITE-PCA-KNN"
        self.history = []
        self.frame_confidences = []
        self.last_screen_rect = None
        self.screen_miss_count = 0

        weight_bytes = _decode_model_data(weight_data)
        exemplar_bytes = _decode_model_data(exemplar_data)
        self.label_bytes = _decode_model_data(label_data)

        self.weights = np.array(
            np.frombuffer(weight_bytes, dtype=np.int8),
            dtype=np.float,
        ).reshape((self.components, self.feature_count))
        self.weight_scales = np.array(weight_scales, dtype=np.float)
        self.biases = np.array(biases, dtype=np.float)

        # Float exemplars prevent int8 subtraction overflow. N6 SDRAM is
        # sufficient for either model; only the selected one is expanded.
        self.exemplars = np.array(
            np.frombuffer(exemplar_bytes, dtype=np.int8),
            dtype=np.float,
        ).reshape((self.exemplar_count, self.components))
        self.exemplar_norms = np.sum(
            self.exemplars * self.exemplars,
            axis=1,
        )

    def reset_history(self):
        self.history = []
        self.frame_confidences = []

    @staticmethod
    def _blob_rect(blob):
        # OpenMV v5 fields are attributes; older releases used methods.
        value = blob.rect
        if isinstance(value, tuple):
            return value
        return value()

    @staticmethod
    def _blob_pixels(blob):
        value = blob.pixels
        if isinstance(value, int):
            return value
        return value()

    @staticmethod
    def _select_trace_blob(mask):
        frame_width = mask.width()
        frame_height = mask.height()
        blobs = mask.find_blobs(
            [(1, 255)],
            x_stride=1,
            y_stride=1,
            area_threshold=500,
            pixels_threshold=250,
            merge=False,
        )

        best_blob = None
        best_score = -1.0
        for blob in blobs:
            x, y, width, height = PcaRatioClassifier._blob_rect(blob)
            center_x = x + (0.5 * width)
            aspect = width / max(1.0, height)
            if width < (0.18 * frame_width):
                continue
            if width > (0.90 * frame_width):
                continue
            if height < (0.25 * frame_height):
                continue
            if height > (0.95 * frame_height):
                continue
            if aspect < 0.60 or aspect > 1.70:
                continue
            if center_x < (0.10 * frame_width):
                continue
            if center_x > (0.90 * frame_width):
                continue

            score = (
                PcaRatioClassifier._blob_pixels(blob)
                * height
                * height
                / (width + 1.0)
            )
            if score > best_score:
                best_blob = blob
                best_score = score
        return best_blob

    @staticmethod
    def _select_white_frame_blob(mask):
        frame_width = mask.width()
        frame_height = mask.height()
        blobs = mask.find_blobs(
            [(1, 255)],
            x_stride=1,
            y_stride=1,
            area_threshold=500,
            pixels_threshold=250,
            merge=True,
            margin=2,
        )

        best_blob = None
        best_score = -1.0
        for blob in blobs:
            x, y, width, height = PcaRatioClassifier._blob_rect(blob)
            center_x = x + (0.5 * width)
            center_y = y + (0.5 * height)
            aspect = width / max(1.0, height)

            if width < (0.22 * frame_width):
                continue
            if width > (0.52 * frame_width):
                continue
            if height < (0.35 * frame_height):
                continue
            if height > (0.82 * frame_height):
                continue
            if aspect < 0.62 or aspect > 1.35:
                continue
            if center_x < (0.36 * frame_width):
                continue
            if center_x > (0.68 * frame_width):
                continue
            if center_y < (0.20 * frame_height):
                continue
            if center_y > (0.80 * frame_height):
                continue

            pixels = PcaRatioClassifier._blob_pixels(blob)
            if (pixels * 5) < (width * height):
                continue
            if pixels > best_score:
                best_blob = blob
                best_score = pixels
        return best_blob

    def _make_trace_mask(self, frame):
        green = frame.to_grayscale(rgb_channel=1, copy=True)
        red_difference = frame.to_grayscale(rgb_channel=0, copy=True)
        blue_difference = frame.to_grayscale(rgb_channel=2, copy=True)

        red_difference.rsub(green)
        red_difference.binary([(self.green_minus_red_min, 255)])
        blue_difference.rsub(green)
        blue_difference.binary([(self.green_minus_blue_min, 255)])
        red_difference.b_and(blue_difference)
        red_difference.dilate(self.mask_dilation)
        return red_difference

    def _make_screen_mask(self, frame):
        dark_screen = frame.to_grayscale(copy=True)
        dark_screen.binary([(0, self.screen_dark_max)])
        return dark_screen

    def _trace_patch_rect(self, blob_rect, frame_width, frame_height):
        x, y, width, height = blob_rect
        side = width - (2 * self.mask_dilation)
        if side < 32:
            return None

        center_x = x + (0.5 * width)
        center_y = y + (0.5 * height)
        square_x = int(round(center_x - (0.5 * side)))
        square_y = int(round(center_y - (0.5 * side)))
        margin = int(round(side * 2.0 / 36.0))
        inner_side = side - (2 * margin)
        patch_x = square_x + margin
        patch_y = square_y + margin

        if patch_x < 0 or patch_y < 0:
            return None
        if patch_x + inner_side > frame_width:
            return None
        if patch_y + inner_side > frame_height:
            return None
        return (patch_x, patch_y, inner_side, inner_side)

    def _white_frame_patch_rect(
        self,
        blob_rect,
        frame_width,
        frame_height,
    ):
        x, y, width, height = blob_rect
        margin_x = max(
            1,
            int(round(
                width * self.screen_margin_x1000 / 1000.0
            )),
        )
        margin_y = max(
            1,
            int(round(
                height * self.screen_margin_x1000 / 1000.0
            )),
        )
        patch_x = x + margin_x
        patch_y = y + margin_y
        patch_width = width - (2 * margin_x)
        patch_height = height - (2 * margin_y)
        if patch_width < 32 or patch_height < 32:
            return None
        if patch_x < 0 or patch_y < 0:
            return None
        if patch_x + patch_width > frame_width:
            return None
        if patch_y + patch_height > frame_height:
            return None
        return (
            patch_x,
            patch_y,
            patch_width,
            patch_height,
        )

    def _extract_feature(self, frame, patch_rect):
        scale_offset = (
            0.01
            if self.model_kind == MODEL_KIND_WHITE_FRAME
            else 0.0
        )
        scale_numerator = self.feature_side + scale_offset
        patch = frame.to_grayscale(
            x_scale=scale_numerator / float(patch_rect[2]),
            y_scale=scale_numerator / float(patch_rect[3]),
            roi=patch_rect,
            hint=omv_image.BILINEAR,
            copy=True,
        )
        if (
            patch.width() != self.feature_side
            or patch.height() != self.feature_side
        ):
            return None

        feature = patch.to_ndarray("f").flatten()
        mean = np.mean(feature)
        std = np.std(feature)
        if std < 3.0:
            return None
        return (feature - mean) / std

    def _classify_feature(self, feature):
        projection = (
            np.dot(self.weights, feature) * self.weight_scales
        ) + self.biases

        # OpenMV v5 ulab has no np.round().
        quantized_values = []
        for component in range(self.components):
            value = (
                float(projection[component])
                * self.projection_quantization
            )
            if value >= 0.0:
                value = int(value + 0.5)
            else:
                value = int(value - 0.5)
            quantized_values.append(int(_clamp(value, -127, 127)))
        quantized = np.array(quantized_values, dtype=np.float)

        quantized_norm = float(np.sum(quantized * quantized))
        distances = (
            self.exemplar_norms
            - (2.0 * np.dot(self.exemplars, quantized))
            + quantized_norm
        )
        nearest_index = int(np.argmin(distances))
        best_label = self.label_bytes[nearest_index]
        nearest_distance = float(distances[nearest_index])

        second_distance = 1.0e30
        if self.model_kind == MODEL_KIND_WHITE_FRAME:
            # The optimized dataset has exactly 20 exemplars per label.
            # Repeated ulab argmin calls avoid scanning 1820 distances in
            # interpreted Python.
            for _ in range(21):
                candidate_index = int(np.argmin(distances))
                candidate_distance = float(distances[candidate_index])
                if self.label_bytes[candidate_index] != best_label:
                    second_distance = candidate_distance
                    break
                distances[candidate_index] = 1.0e30
        else:
            for index in range(self.exemplar_count):
                if self.label_bytes[index] == best_label:
                    continue
                distance = float(distances[index])
                if distance < second_distance:
                    second_distance = distance

        if second_distance <= 0.0:
            frame_confidence = 0
        else:
            frame_confidence = int(
                100.0
                * (second_distance - nearest_distance)
                / second_distance
            )
        frame_confidence = int(_clamp(frame_confidence, 0, 99))
        return (
            int(best_label),
            frame_confidence,
            nearest_distance,
            second_distance,
        )

    def analyze(self, frame, scan_frequency_hz=1000):
        started = _ticks_ms()
        result = self.result.clear()

        if self.model_kind == MODEL_KIND_WHITE_FRAME:
            mask = self._make_screen_mask(frame)
            blob = self._select_white_frame_blob(mask)
            if blob is None:
                self.screen_miss_count += 1
                if (
                    self.last_screen_rect is None
                    or self.screen_miss_count > self.screen_hold_frames
                ):
                    self.last_screen_rect = None
                    self.reset_history()
                    result.failure_reason = "NO_SCREEN"
                    result.analysis_ms = _ticks_diff(
                        _ticks_ms(),
                        started,
                    )
                    return result
                blob_rect = self.last_screen_rect
                result.tracked_rect = True
            else:
                blob_rect = self._blob_rect(blob)
                self.last_screen_rect = blob_rect
                self.screen_miss_count = 0
            patch_rect = self._white_frame_patch_rect(
                blob_rect,
                frame.width(),
                frame.height(),
            )
        else:
            mask = self._make_trace_mask(frame)
            blob = self._select_trace_blob(mask)
            if blob is None:
                self.reset_history()
                result.analysis_ms = _ticks_diff(
                    _ticks_ms(),
                    started,
                )
                return result
            blob_rect = self._blob_rect(blob)
            patch_rect = self._trace_patch_rect(
                blob_rect,
                frame.width(),
                frame.height(),
            )

        if patch_rect is None:
            self.reset_history()
            result.failure_reason = "BAD_ROI"
            result.analysis_ms = _ticks_diff(_ticks_ms(), started)
            return result

        feature = self._extract_feature(frame, patch_rect)
        if feature is None:
            self.reset_history()
            result.failure_reason = "BAD_PATCH"
            result.analysis_ms = _ticks_diff(_ticks_ms(), started)
            return result

        (
            label,
            frame_confidence,
            nearest_distance,
            second_distance,
        ) = self._classify_feature(feature)

        self.history.append(label)
        self.frame_confidences.append(frame_confidence)
        if len(self.history) > self.fusion_frames:
            self.history.pop(0)
            self.frame_confidences.pop(0)

        ordered = sorted(self.history)
        fused_label = ordered[len(ordered) // 2]
        ratio = 1.0 + (0.1 * fused_label)
        frame_ratio = 1.0 + (0.1 * label)

        deviations = sorted(
            abs(value - fused_label) for value in self.history
        )
        median_deviation = deviations[len(deviations) // 2]
        stability_confidence = int(
            _clamp(100 - (25 * median_deviation), 0, 100)
        )
        distance_confidence = (
            sum(self.frame_confidences)
            // max(1, len(self.frame_confidences))
        )
        confidence = int(
            (0.45 * distance_confidence)
            + (0.55 * stability_confidence)
        )
        if len(self.history) < self.fusion_frames:
            confidence = min(confidence, 44)

        result.found = True
        result.rect = blob_rect
        result.patch_rect = patch_rect
        result.frame_ratio = frame_ratio
        result.ratio = ratio
        result.estimated_frequency_hz = int(
            round(ratio * scan_frequency_hz / 100.0) * 100
        )
        result.confidence = int(_clamp(confidence, 0, 99))
        result.stable_frames = len(self.history)
        result.predictions = tuple(
            1.0 + (0.1 * value) for value in self.history
        )
        result.nearest_distance = nearest_distance
        result.second_distance = second_distance
        result.accepted = (
            len(self.history) >= self.fusion_frames
            and result.confidence >= self.accept_confidence
        )
        result.analysis_ms = _ticks_diff(_ticks_ms(), started)
        return result

# ========================= UART PROTOCOL ==========================

PROTOCOL_VERSION = 0x01
FRAME_HEAD_0 = 0xAA
FRAME_HEAD_1 = 0x55
MAX_PAYLOAD = 64

TYPE_ACK = 0x01
TYPE_NACK = 0x02
TYPE_HEARTBEAT = 0x03
TYPE_START_TASK = 0x10
TYPE_COARSE_RESULT = 0x11
TYPE_DDS_TEST = 0x20
TYPE_DDS_TEST_RESULT = 0x21
TYPE_STOP_TASK = 0x22
TYPE_OPENMV_ERROR = 0x7F

ACK_ACCEPTED = 0x00
ACK_DUPLICATE = 0x01
ACK_ASYNC = 0x02

ERR_LENGTH = 0x01
ERR_VERSION = 0x02
ERR_LOCK_MODE = 0x03
ERR_SAW_FREQUENCY = 0x04
ERR_BUSY = 0x05
ERR_STATE = 0x06
ERR_SESSION = 0x07
ERR_RANGE = 0x08
ERR_CAMERA = 0x09
ERR_INTERNAL = 0x0A


def crc16_modbus(data):
    crc = 0xFFFF
    for value in data:
        crc ^= value
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ 0xA001
            else:
                crc >>= 1
    return crc & 0xFFFF


def encode_frame(message_type, sequence, payload=b""):
    payload = bytes(payload)
    length = len(payload)
    if length > MAX_PAYLOAD:
        raise ValueError("payload exceeds 64 bytes")

    body = bytearray(5 + length)
    body[0] = PROTOCOL_VERSION
    body[1] = message_type & 0xFF
    body[2] = sequence & 0xFF
    body[3] = length & 0xFF
    body[4] = (length >> 8) & 0xFF
    body[5:] = payload
    crc = crc16_modbus(body)

    frame = bytearray(2 + len(body) + 2)
    frame[0] = FRAME_HEAD_0
    frame[1] = FRAME_HEAD_1
    frame[2:2 + len(body)] = body
    frame[-2] = crc & 0xFF
    frame[-1] = (crc >> 8) & 0xFF
    return bytes(frame)


class FrameParser:
    """Persistent parser tolerant of noise, partial frames, and sticky frames."""

    def __init__(self):
        self.buffer = bytearray()
        self.crc_error_count = 0
        self.oversize_count = 0
        self.noise_byte_count = 0

    def _align_header(self):
        count = len(self.buffer)
        index = 0
        while index + 1 < count:
            if (
                self.buffer[index] == FRAME_HEAD_0
                and self.buffer[index + 1] == FRAME_HEAD_1
            ):
                if index:
                    self.noise_byte_count += index
                    # OpenMV v5.0.0 / MicroPython v1.28 on N6 does not
                    # implement bytearray item deletion. A bytearray slice
                    # remains a bytearray on this firmware.
                    self.buffer = self.buffer[index:]
                return True
            index += 1

        # Keep a trailing 0xAA because it may be the first byte of a split
        # header. Everything else is confirmed noise.
        keep = 1 if count and self.buffer[-1] == FRAME_HEAD_0 else 0
        discard = count - keep
        if discard:
            self.noise_byte_count += discard
            self.buffer = self.buffer[discard:]
        return False

    def feed(self, data):
        if data:
            self.buffer.extend(data)

        frames = []
        while True:
            if not self._align_header():
                break
            if len(self.buffer) < 7:
                break

            payload_length = self.buffer[5] | (self.buffer[6] << 8)
            if payload_length > MAX_PAYLOAD:
                self.oversize_count += 1
                self.buffer = self.buffer[2:]
                continue

            total_length = 9 + payload_length
            if len(self.buffer) < total_length:
                break

            crc_index = 7 + payload_length
            received_crc = (
                self.buffer[crc_index]
                | (self.buffer[crc_index + 1] << 8)
            )
            calculated_crc = crc16_modbus(
                self.buffer[2:crc_index]
            )
            if received_crc != calculated_crc:
                self.crc_error_count += 1
                # Drop one byte and search again. This recovers even when a
                # corrupted LEN accidentally spans into the following frame.
                self.buffer = self.buffer[1:]
                continue

            raw = bytes(self.buffer[:total_length])
            frames.append(
                (
                    self.buffer[2],
                    self.buffer[3],
                    self.buffer[4],
                    bytes(self.buffer[7:crc_index]),
                    raw,
                )
            )
            self.buffer = self.buffer[total_length:]
        return frames


class ProtocolLink:
    def __init__(self, uart):
        self.uart = uart
        self.parser = FrameParser()
        self.tx_sequence = 0

    def poll(self):
        available = self.uart.any()
        if not available:
            return ()
        data = self.uart.read(available)
        if not data:
            return ()
        return self.parser.feed(data)

    def send_new(self, message_type, payload=b""):
        sequence = self.tx_sequence
        self.tx_sequence = (self.tx_sequence + 1) & 0xFF
        frame = encode_frame(message_type, sequence, payload)
        self.uart.write(frame)
        return frame, sequence

    def resend(self, frame):
        self.uart.write(frame)

    def send_ack(self, received_type, received_sequence, status):
        payload = bytes((
            received_type & 0xFF,
            received_sequence & 0xFF,
            status & 0xFF,
        ))
        return self.send_new(TYPE_ACK, payload)

    def send_nack(self, received_type, received_sequence, error_code):
        payload = bytes((
            received_type & 0xFF,
            received_sequence & 0xFF,
            error_code & 0xFF,
        ))
        return self.send_new(TYPE_NACK, payload)

# ========================== SSD1309 OLED ==========================

try:
    import micropython
    _native = getattr(micropython, "native", None)
except ImportError:
    _native = None

if _native is None:
    def _native(function):
        return function


PANEL_WIDTH = 128
PANEL_HEIGHT = 64
OLED_WIDTH = 64
OLED_HEIGHT = 32


def _ticks_ms():
    function = getattr(time, "ticks_ms", None)
    if function:
        return function()
    return int(time.time() * 1000)


def _ticks_diff(new, old):
    function = getattr(time, "ticks_diff", None)
    if function:
        return function(new, old)
    return new - old


def _adjust_threshold(value, brightness, contrast_percent):
    delta = value - 128
    if delta < 0:
        value = 128 - ((-delta * 100) // contrast_percent)
    else:
        value = 128 + ((delta * 100) // contrast_percent)
    value -= brightness
    if value < 0:
        return 0
    if value > 255:
        return 255
    return value


@_native
def _pack_grayscale(
    src,
    dst,
    source_width,
    x_map,
    y_map,
    threshold_x0,
    threshold_x1,
    threshold_x2,
    threshold_x3,
):
    output = 1
    for page in range(OLED_HEIGHT // 8):
        y = page * 8
        row0 = y_map[y] * source_width
        row1 = y_map[y + 1] * source_width
        row2 = y_map[y + 2] * source_width
        row3 = y_map[y + 3] * source_width
        row4 = y_map[y + 4] * source_width
        row5 = y_map[y + 5] * source_width
        row6 = y_map[y + 6] * source_width
        row7 = y_map[y + 7] * source_width

        for x in range(OLED_WIDTH):
            source_x = x_map[x]
            dst[output] = (
                (1 if src[row0 + source_x] >= threshold_x0[x] else 0)
                | (2 if src[row1 + source_x] >= threshold_x1[x] else 0)
                | (4 if src[row2 + source_x] >= threshold_x2[x] else 0)
                | (8 if src[row3 + source_x] >= threshold_x3[x] else 0)
                | (16 if src[row4 + source_x] >= threshold_x0[x] else 0)
                | (32 if src[row5 + source_x] >= threshold_x1[x] else 0)
                | (64 if src[row6 + source_x] >= threshold_x2[x] else 0)
                | (128 if src[row7 + source_x] >= threshold_x3[x] else 0)
            )
            output += 1


@_native
def _pack_rgb565(
    src,
    dst,
    source_width,
    x_map,
    y_map,
    threshold_x0,
    threshold_x1,
    threshold_x2,
    threshold_x3,
):
    """Downsample a little-endian RGB565 frame directly into SSD1309 pages."""
    output = 1
    for page in range(OLED_HEIGHT // 8):
        y = page * 8
        row0 = y_map[y] * source_width
        row1 = y_map[y + 1] * source_width
        row2 = y_map[y + 2] * source_width
        row3 = y_map[y + 3] * source_width
        row4 = y_map[y + 4] * source_width
        row5 = y_map[y + 5] * source_width
        row6 = y_map[y + 6] * source_width
        row7 = y_map[y + 7] * source_width
        rows = (row0, row1, row2, row3, row4, row5, row6, row7)

        for x in range(OLED_WIDTH):
            source_x = x_map[x]
            bits = 0
            for bit in range(8):
                byte_index = (rows[bit] + source_x) << 1
                pixel = src[byte_index] | (src[byte_index + 1] << 8)
                red5 = (pixel >> 11) & 0x1F
                green6 = (pixel >> 5) & 0x3F
                blue5 = pixel & 0x1F
                gray = (
                    (red5 * 616)
                    + (green6 * 600)
                    + (blue5 * 232)
                ) >> 8
                phase = bit & 3
                if phase == 0:
                    threshold = threshold_x0[x]
                elif phase == 1:
                    threshold = threshold_x1[x]
                elif phase == 2:
                    threshold = threshold_x2[x]
                else:
                    threshold = threshold_x3[x]
                if gray >= threshold:
                    bits |= 1 << bit
            dst[output] = bits
            output += 1


class AimDisplay:
    def __init__(
        self,
        max_fps=3,
        brightness=0,
        contrast_percent=200,
        oled_contrast=0xFF,
        address=0x3C,
        column_offset=0,
        hardware_bus=2,
        scl_pin="P4",
        sda_pin="P5",
        allow_soft_fallback=True,
        fast_start=False,
        clear_on_start=True,
        self_test=True,
    ):
        if max_fps <= 0:
            raise ValueError("max_fps must be positive")
        if contrast_percent <= 0:
            raise ValueError("contrast_percent must be positive")

        self.enabled = True
        self.period_ms = max(1, 1000 // max_fps)
        self.last_update = None
        self.last_duration_ms = 0
        self.update_count = 0
        self.error_count = 0
        self.source_width = 0
        self.source_height = 0
        self.x_map = None
        self.y_map = None

        self.address_requested = address
        self.column_offset = column_offset
        self.oled_contrast = oled_contrast
        self.tx = bytearray(1 + (OLED_WIDTH * OLED_HEIGHT // 8))
        self.tx[0] = 0x40

        rows = (
            (8, 136, 40, 168),
            (200, 72, 232, 104),
            (56, 184, 24, 152),
            (248, 120, 216, 88),
        )
        adjusted = []
        for row in rows:
            adjusted.append(tuple(
                _adjust_threshold(value, brightness, contrast_percent)
                for value in row
            ))
        self.threshold_x0 = bytes(
            adjusted[0][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x1 = bytes(
            adjusted[1][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x2 = bytes(
            adjusted[2][x & 3] for x in range(OLED_WIDTH)
        )
        self.threshold_x3 = bytes(
            adjusted[3][x & 3] for x in range(OLED_WIDTH)
        )

        self.i2c, self.address, self.bus_mode, self.bus_frequency = (
            self._open_bus(
                hardware_bus,
                scl_pin,
                sda_pin,
                allow_soft_fallback,
                fast_start,
            )
        )
        first_column = (
            self.column_offset + ((PANEL_WIDTH - OLED_WIDTH) // 2)
        )
        first_page = (PANEL_HEIGHT - OLED_HEIGHT) // 16
        self.window = bytes((
            0x00,
            0x21, first_column, first_column + OLED_WIDTH - 1,
            0x22,
            first_page,
            first_page + (OLED_HEIGHT // 8) - 1,
        ))
        self._init_display(clear_panel=clear_on_start)
        if self_test:
            self._show_self_test()

    def _select_address(self, found):
        for candidate in (self.address_requested, 0x3C, 0x3D):
            if candidate in found:
                return candidate
        return None

    def _open_bus(
        self,
        hardware_bus,
        scl_pin,
        sda_pin,
        allow_soft_fallback,
        fast_start,
    ):
        if fast_start:
            # The competition wiring is fixed and already verified:
            # P7=SCL, P8=SDA, 100 kHz, address 0x3C. Do not spend time
            # scanning four bus/frequency combinations at every boot.
            bus = SoftI2C(
                scl=Pin(scl_pin),
                sda=Pin(sda_pin),
                freq=100_000,
            )
            return (
                bus,
                self.address_requested,
                "software",
                100_000,
            )

        for frequency in (400_000, 100_000):
            bus = None
            try:
                bus = I2C(hardware_bus, freq=frequency)
                found = bus.scan()
                address = self._select_address(found)
                if address is not None:
                    return bus, address, "hardware", frequency
            except (OSError, ValueError):
                pass
            if bus is not None:
                try:
                    bus.deinit()
                except (AttributeError, OSError):
                    pass

        if allow_soft_fallback:
            # P7/P8 uses bit-banged I2C on N6. Long wires and typical OLED
            # pull-ups repeatedly NACKed at 400 kHz in the user's log.
            for frequency in (100_000, 50_000):
                try:
                    bus = SoftI2C(
                        scl=Pin(scl_pin),
                        sda=Pin(sda_pin),
                        freq=frequency,
                    )
                    found = bus.scan()
                    address = self._select_address(found)
                    if address is not None:
                        return bus, address, "software", frequency
                except (OSError, ValueError):
                    pass

        raise RuntimeError(
            "SSD1309 not found on P4/P5 or P7/P8; check 3V3/GND/pull-ups"
        )

    def _commands(self, values):
        packet = bytearray(len(values) + 1)
        packet[0] = 0x00
        packet[1:] = values
        self.i2c.writeto(self.address, packet)

    def _init_display(self, clear_panel=True):
        self._commands(bytes((
            0xAE,
            0xD5, 0x80,
            0xA8, 0x3F,
            0xD3, 0x00,
            0x40,
            0x20, 0x00,
            0xA1,
            0xC8,
            0xDA, 0x12,
            0x81, self.oled_contrast,
            0xD9, 0xF1,
            0xDB, 0x40,
            0xA4,
            0xA6,
            0xAF,
        )))
        if clear_panel:
            self._clear_panel()

    def _clear_panel(self):
        """Clear the 128x64 RAM in short page writes to avoid SoftI2C NACKs."""
        packet = bytearray(1 + PANEL_WIDTH)
        packet[0] = 0x40
        for page in range(PANEL_HEIGHT // 8):
            window = bytes((
                0x00,
                0x21, self.column_offset,
                self.column_offset + PANEL_WIDTH - 1,
                0x22, page, page,
            ))
            self.i2c.writeto(self.address, window)
            self.i2c.writeto(self.address, packet)

    def _show(self):
        self.i2c.writeto(self.address, self.window)
        self.i2c.writeto(self.address, self.tx)

    def _show_self_test(self):
        """Show a border and X immediately so wiring is visible at boot."""
        for page in range(OLED_HEIGHT // 8):
            for x in range(OLED_WIDTH):
                value = 0
                if page == 0:
                    value |= 0x01
                if page == (OLED_HEIGHT // 8) - 1:
                    value |= 0x80
                if x == 0 or x == OLED_WIDTH - 1:
                    value = 0xFF

                y0 = (x * (OLED_HEIGHT - 1)) // (OLED_WIDTH - 1)
                y1 = (OLED_HEIGHT - 1) - y0
                if (y0 >> 3) == page:
                    value |= 1 << (y0 & 7)
                if (y1 >> 3) == page:
                    value |= 1 << (y1 & 7)
                self.tx[1 + (page * OLED_WIDTH) + x] = value
        self._show()
        self.last_update = _ticks_ms()

    def _ensure_maps(self, width, height):
        if width < 2 or height < 2:
            raise ValueError("source image must be at least 2x2")
        if width == self.source_width and height == self.source_height:
            return
        self.source_width = width
        self.source_height = height
        self.x_map = array(
            "H",
            [
                (x * (width - 1)) // (OLED_WIDTH - 1)
                for x in range(OLED_WIDTH)
            ],
        )
        self.y_map = array(
            "H",
            [
                (y * (height - 1)) // (OLED_HEIGHT - 1)
                for y in range(OLED_HEIGHT)
            ],
        )

    def set_max_fps(self, max_fps):
        if max_fps <= 0:
            raise ValueError("max_fps must be positive")
        self.period_ms = max(1, 1000 // max_fps)

    def update_if_due(self, frame, now_ms=None, force=False):
        if not self.enabled:
            return False
        if now_ms is None:
            now_ms = _ticks_ms()
        if (
            not force
            and self.last_update is not None
            and _ticks_diff(now_ms, self.last_update) < self.period_ms
        ):
            return False

        start = _ticks_ms()
        width = frame.width()
        height = frame.height()
        self._ensure_maps(width, height)
        source = frame.bytearray()
        packer = (
            _pack_grayscale
            if frame.format() == omv_image.GRAYSCALE
            else _pack_rgb565
        )
        packer(
            source,
            self.tx,
            self.source_width,
            self.x_map,
            self.y_map,
            self.threshold_x0,
            self.threshold_x1,
            self.threshold_x2,
            self.threshold_x3,
        )

        # Four blinking pixels in the top-right corner prove that the OLED
        # loop is alive even when the camera and scope image are stationary.
        heartbeat_on = (self.update_count & 1) == 0
        for x in range(OLED_WIDTH - 4, OLED_WIDTH):
            index = 1 + x
            if heartbeat_on:
                self.tx[index] |= 0x0F
            else:
                self.tx[index] &= 0xF0

        self._show()
        done = _ticks_ms()
        self.last_duration_ms = _ticks_diff(done, start)
        self.last_update = now_ms
        self.update_count += 1
        self.error_count = 0
        return True

# ============================= APP ================================

STATE_IDLE = 0
STATE_COARSE = 1
STATE_WAIT_DDS = 2
STATE_DDS_RECOGNIZING = 3


def ticks_ms():
    return time.ticks_ms()


def ticks_diff(new, old):
    return time.ticks_diff(new, old)


def ticks_add(value, delta):
    return time.ticks_add(value, delta)


def clamp_int(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return int(value)


def setup_camera():
    camera = csi.CSI(stream=IDE_STREAM_ENABLED)
    camera.reset()
    camera.pixformat(csi.RGB565)
    camera.framesize(csi.QVGA)
    camera.snapshot(time=CAMERA_SETTLE_MS)

    if FREEZE_AUTO_CONTROLS:
        try:
            camera.auto_gain(False)
        except (AttributeError, OSError):
            pass
        try:
            camera.auto_exposure(False)
        except (AttributeError, OSError):
            pass
        try:
            camera.auto_whitebal(False)
        except (AttributeError, OSError):
            pass
    return camera


def setup_display():
    if not OLED_ENABLED:
        print("【OLED】已关闭")
        return None
    try:
        return AimDisplay(
            max_fps=OLED_MAX_FPS,
            contrast_percent=OLED_CONTRAST_PERCENT,
            address=OLED_ADDRESS,
            column_offset=OLED_COLUMN_OFFSET,
            hardware_bus=OLED_I2C_ID,
            scl_pin=OLED_SCL_PIN,
            sda_pin=OLED_SDA_PIN,
            allow_soft_fallback=True,
            fast_start=OLED_FAST_START,
            clear_on_start=False,
            self_test=False,
        )
    except (ImportError, RuntimeError, ValueError, OSError) as error:
        print("【OLED】未连接，串口识别不受影响：%s" % error)
        return None


def setup_uart():
    # OpenMV v5.0.0 on N6 selects the pins from the UART peripheral ID and
    # rejects the generic MicroPython tx/rx/txbuf/rxbuf keywords. UART7 is
    # fixed to P14=TX and P13=RX; its defaults are 8 data bits, no parity,
    # one stop bit. Keep the constructor minimal for this exact firmware.
    return UART(UART_ID, UART_BAUDRATE)


def consensus(history, minimum_samples):
    if len(history) < minimum_samples:
        return None

    best_group = None
    best_spread = 1.0e30
    for center in history:
        group = [
            value
            for value in history
            if abs(value - center) <= COARSE_CLUSTER_RADIUS
        ]
        spread = sum(abs(value - center) for value in group)
        if (
            best_group is None
            or len(group) > len(best_group)
            or (len(group) == len(best_group) and spread < best_spread)
        ):
            best_group = group
            best_spread = spread

    ordered = sorted(best_group)
    ratio = ordered[len(ordered) // 2]
    confidence = int(100 * len(best_group) / len(history))
    return ratio, confidence, len(best_group), len(history)


def annotate(frame, controller, fps):
    state_names = ("IDLE", "COARSE", "WAIT DDS", "DDS")
    state_name = state_names[controller.state]
    frame.draw_rectangle(
        (0, 0, frame.width(), 39),
        color=(0, 0, 0),
        fill=True,
    )
    frame.draw_string(
        (2, 1),
        "TASK5 UART7  %s" % state_name,
        color=(80, 255, 80),
        scale=1,
    )
    frame.draw_string(
        (2, 14),
        "SCAN:%5dHz  EST:%6dHz" % (
            controller.saw_frequency_hz,
            controller.coarse_estimated_hz,
        ),
        color=(255, 255, 255),
        scale=1,
    )
    frame.draw_string(
        (2, 27),
        "RATIO:%4.1fx CONF:%2d%% FPS:%3.1f" % (
            controller.display_ratio,
            controller.coarse_confidence,
            fps,
        ),
        color=(200, 220, 255),
        scale=1,
    )
    if controller.last_rect is not None:
        frame.draw_rectangle(
            controller.last_rect,
            color=(40, 255, 40),
            thickness=2,
        )


class Task5Controller:
    def __init__(self, link):
        self.link = link
        self.state = STATE_IDLE
        self.session_id = 0
        self.lock_mode = 0
        self.saw_frequency_hz = 0
        self.start_command_key = None
        self.last_completed_session = 0

        self.classifier = None
        self.pending_model_spec = None
        self.coarse_started_ms = 0
        self.coarse_history = []
        self.coarse_estimated_hz = 0
        self.coarse_confidence = 0
        self.display_ratio = 0.0
        self.last_rect = None

        self.last_result_type = 0
        self.last_result_sequence = 0
        self.last_result_frame = None
        self.last_result_waiting_ack = False

        self.dds_command_key = None
        self.dds_test_id = 0
        self.dds_frequency_hz = 0
        self.dds_search_stage = 0
        self.dds_capture_due_ms = 0
        self.last_stop_key = None

    def _cache_and_send_result(self, message_type, payload):
        frame, sequence = self.link.send_new(message_type, payload)
        self.last_result_type = message_type
        self.last_result_sequence = sequence
        self.last_result_frame = frame
        self.last_result_waiting_ack = True

    def _clear_result_cache(self):
        self.last_result_type = 0
        self.last_result_sequence = 0
        self.last_result_frame = None
        self.last_result_waiting_ack = False

    def _reset_to_idle(self, completed_session=0):
        if completed_session:
            self.last_completed_session = completed_session
        self.state = STATE_IDLE
        self.session_id = 0
        self.lock_mode = 0
        self.saw_frequency_hz = 0
        self.start_command_key = None
        self.classifier = None
        self.pending_model_spec = None
        self.coarse_started_ms = 0
        self.coarse_history = []
        self.coarse_estimated_hz = 0
        self.coarse_confidence = 0
        self.display_ratio = 0.0
        self.last_rect = None
        self.dds_command_key = None
        self.dds_test_id = 0
        self.dds_frequency_hz = 0
        self.dds_search_stage = 0
        self.dds_capture_due_ms = 0
        self._clear_result_cache()
        gc.collect()

    def _send_cached_result(self, expected_type):
        if (
            self.last_result_frame is not None
            and self.last_result_type == expected_type
        ):
            self.link.resend(self.last_result_frame)
            return True
        return False

    def _handle_ack(self, payload):
        if len(payload) != 3:
            return
        ack_type, ack_sequence, _status = payload
        if (
            ack_type == self.last_result_type
            and ack_sequence == self.last_result_sequence
        ):
            self.last_result_waiting_ack = False
            if CONSOLE_DEBUG:
                print(
                    "【串口】结果0x%02X已收到ACK"
                    % self.last_result_type
                )

    def _handle_start(self, sequence, payload, command_key):
        if len(payload) != 7:
            self.link.send_nack(TYPE_START_TASK, sequence, ERR_LENGTH)
            return
        session_id, lock_mode, saw_frequency_hz = struct.unpack(
            "<HBI",
            payload,
        )
        if not session_id:
            self.link.send_nack(TYPE_START_TASK, sequence, ERR_SESSION)
            return
        if lock_mode > 2:
            self.link.send_nack(TYPE_START_TASK, sequence, ERR_LOCK_MODE)
            return
        if saw_frequency_hz not in (1000, 10000):
            self.link.send_nack(
                TYPE_START_TASK,
                sequence,
                ERR_SAW_FREQUENCY,
            )
            return

        if self.state != STATE_IDLE:
            if command_key == self.start_command_key:
                self.link.send_ack(
                    TYPE_START_TASK,
                    sequence,
                    ACK_DUPLICATE,
                )
                self._send_cached_result(TYPE_COARSE_RESULT)
                return
            if session_id != self.session_id:
                self.link.send_nack(
                    TYPE_START_TASK,
                    sequence,
                    ERR_SESSION,
                )
            else:
                self.link.send_nack(
                    TYPE_START_TASK,
                    sequence,
                    ERR_BUSY,
                )
            return

        if session_id == self.last_completed_session:
            self.link.send_nack(TYPE_START_TASK, sequence, ERR_SESSION)
            return

        # ACK is deliberately sent before model expansion or recognition.
        self.link.send_ack(
            TYPE_START_TASK,
            sequence,
            ACK_ACCEPTED,
        )
        self.state = STATE_COARSE
        self.session_id = session_id
        self.lock_mode = lock_mode
        self.saw_frequency_hz = saw_frequency_hz
        self.start_command_key = command_key
        self.pending_model_spec = (
            MODEL_1K_SPEC
            if saw_frequency_hz == 1000
            else MODEL_10K_SPEC
        )
        self.classifier = None
        self.coarse_started_ms = ticks_ms()
        self.coarse_history = []
        self.coarse_estimated_hz = 0
        self.coarse_confidence = 0
        self.display_ratio = 0.0
        self.last_rect = None
        self.dds_command_key = None
        self._clear_result_cache()
        print(
            "【开始粗识别】任务%d，扫描%d Hz，模式%d"
            % (session_id, saw_frequency_hz, lock_mode)
        )

    def _handle_dds_test(self, sequence, payload, command_key):
        if len(payload) != 11:
            self.link.send_nack(TYPE_DDS_TEST, sequence, ERR_LENGTH)
            return
        (
            session_id,
            test_id,
            dds_frequency_hz,
            search_stage,
            capture_delay_ms,
        ) = struct.unpack("<HHIBH", payload)

        if session_id != self.session_id or not session_id:
            self.link.send_nack(TYPE_DDS_TEST, sequence, ERR_SESSION)
            return
        if (
            not test_id
            or dds_frequency_hz < 1
            or dds_frequency_hz > 200000
            or search_stage > 4
            or capture_delay_ms > 5000
        ):
            self.link.send_nack(TYPE_DDS_TEST, sequence, ERR_RANGE)
            return

        if command_key == self.dds_command_key:
            self.link.send_ack(
                TYPE_DDS_TEST,
                sequence,
                ACK_DUPLICATE,
            )
            self._send_cached_result(TYPE_DDS_TEST_RESULT)
            return
        if self.state == STATE_DDS_RECOGNIZING:
            self.link.send_nack(TYPE_DDS_TEST, sequence, ERR_BUSY)
            return
        if self.state != STATE_WAIT_DDS:
            self.link.send_nack(TYPE_DDS_TEST, sequence, ERR_STATE)
            return

        self.link.send_ack(TYPE_DDS_TEST, sequence, ACK_ACCEPTED)
        self.state = STATE_DDS_RECOGNIZING
        self.dds_command_key = command_key
        self.dds_test_id = test_id
        self.dds_frequency_hz = dds_frequency_hz
        self.dds_search_stage = search_stage
        self.dds_capture_due_ms = ticks_add(
            ticks_ms(),
            capture_delay_ms,
        )
        self._clear_result_cache()
        print(
            "【DDS测试】编号%d，频率%d Hz，等待%d ms"
            % (test_id, dds_frequency_hz, capture_delay_ms)
        )

    def _handle_stop(self, sequence, payload, command_key):
        if len(payload) != 3:
            self.link.send_nack(TYPE_STOP_TASK, sequence, ERR_LENGTH)
            return
        session_id, reason = struct.unpack("<HB", payload)

        if self.state == STATE_IDLE:
            if command_key == self.last_stop_key:
                self.link.send_ack(
                    TYPE_STOP_TASK,
                    sequence,
                    ACK_DUPLICATE,
                )
            else:
                self.link.send_nack(
                    TYPE_STOP_TASK,
                    sequence,
                    ERR_SESSION,
                )
            return
        if session_id != self.session_id:
            self.link.send_nack(TYPE_STOP_TASK, sequence, ERR_SESSION)
            return

        self.link.send_ack(TYPE_STOP_TASK, sequence, ACK_ACCEPTED)
        self.last_stop_key = command_key
        print(
            "【任务结束】任务%d，原因%d，已回到空闲"
            % (session_id, reason)
        )
        self._reset_to_idle(completed_session=session_id)

    def handle_received(self, received):
        version, message_type, sequence, payload, _raw = received
        if version != PROTOCOL_VERSION:
            if message_type not in (TYPE_ACK, TYPE_NACK):
                self.link.send_nack(message_type, sequence, ERR_VERSION)
            return

        if message_type == TYPE_ACK:
            self._handle_ack(payload)
            return
        if message_type == TYPE_NACK:
            if CONSOLE_DEBUG:
                print("【串口】收到NACK：%s" % str(tuple(payload)))
            return

        command_key = (message_type, sequence, payload)
        if message_type == TYPE_HEARTBEAT:
            if len(payload) != 0:
                self.link.send_nack(
                    TYPE_HEARTBEAT,
                    sequence,
                    ERR_LENGTH,
                )
            else:
                self.link.send_ack(
                    TYPE_HEARTBEAT,
                    sequence,
                    ACK_ACCEPTED,
                )
        elif message_type == TYPE_START_TASK:
            self._handle_start(sequence, payload, command_key)
        elif message_type == TYPE_DDS_TEST:
            self._handle_dds_test(sequence, payload, command_key)
        elif message_type == TYPE_STOP_TASK:
            self._handle_stop(sequence, payload, command_key)
        else:
            self.link.send_nack(message_type, sequence, ERR_STATE)

    def poll_uart(self):
        for received in self.link.poll():
            self.handle_received(received)

    def prepare_classifier_if_needed(self):
        if (
            self.state != STATE_COARSE
            or self.classifier is not None
            or self.pending_model_spec is None
        ):
            return
        try:
            self.classifier = PcaRatioClassifier(
                self.pending_model_spec,
                fusion_frames=3,
                accept_confidence=45,
            )
            self.pending_model_spec = None
            gc.collect()
        except Exception as error:
            print("【模型错误】无法载入识别模型：%s" % error)
            self.send_coarse_result(2, 0.0, 0)

    def send_coarse_result(self, result_code, ratio, confidence):
        ratio_x1000 = clamp_int(int(ratio * 1000.0 + 0.5), 0, 0xFFFFFFFF)
        debug_count = clamp_int(int(ratio + 0.5), 0, 255)
        payload = struct.pack(
            "<HBIBBB",
            self.session_id,
            result_code,
            ratio_x1000,
            clamp_int(confidence, 0, 100),
            debug_count,
            debug_count,
        )
        self._cache_and_send_result(TYPE_COARSE_RESULT, payload)
        self.state = STATE_WAIT_DDS
        self.display_ratio = ratio
        self.coarse_confidence = clamp_int(confidence, 0, 100)
        self.coarse_estimated_hz = int(
            (self.saw_frequency_hz * ratio_x1000 + 500) // 1000
        )
        self.classifier = None
        self.pending_model_spec = None
        gc.collect()
        if result_code in (0, 1):
            print(
                "【粗识别结果】约%d Hz（%.1f倍），可信度%d%%，已发送"
                % (
                    self.coarse_estimated_hz,
                    ratio,
                    self.coarse_confidence,
                )
            )
        else:
            print("【粗识别失败】结果码%d，已发送" % result_code)

    def process_coarse_frame(self, frame):
        if self.state != STATE_COARSE or self.classifier is None:
            return
        result = self.classifier.analyze(
            frame,
            scan_frequency_hz=self.saw_frequency_hz,
        )
        if result.rect is not None:
            self.last_rect = result.rect
        if result.found:
            self.display_ratio = result.frame_ratio
            self.coarse_history.append(result.frame_ratio)
            if len(self.coarse_history) > COARSE_WINDOW_FRAMES:
                self.coarse_history.pop(0)

        fused = consensus(
            self.coarse_history,
            COARSE_MIN_SAMPLES,
        )
        if fused is not None:
            ratio, confidence, _agreeing, _total = fused
            if confidence >= COARSE_MIN_CONFIDENCE:
                result_code = 0 if confidence >= 70 else 1
                self.send_coarse_result(
                    result_code,
                    ratio,
                    confidence,
                )
                return

        if ticks_diff(ticks_ms(), self.coarse_started_ms) >= (
            COARSE_TIMEOUT_MS
        ):
            if self.coarse_history:
                # Preserve a usable candidate as LOW_CONFIDENCE instead of
                # making the STM32 abort solely because consensus timed out.
                fallback = consensus(self.coarse_history, 1)
                self.send_coarse_result(1, fallback[0], fallback[1])
            else:
                self.send_coarse_result(2, 0.0, 0)

    def process_dds_if_due(self):
        if self.state != STATE_DDS_RECOGNIZING:
            return
        if ticks_diff(ticks_ms(), self.dds_capture_due_ms) < 0:
            return

        if not DDS_NUMERIC_FALLBACK:
            result_code = 5
            match_score = 0
            confidence = 0
        else:
            target_hz = self.coarse_estimated_hz
            if self.lock_mode == 2:
                target_hz *= 2
            target_hz = clamp_int(target_hz, 1, 200000)
            tolerance_hz = max(100, self.saw_frequency_hz // 10)
            error_hz = abs(self.dds_frequency_hz - target_hz)
            if error_hz <= tolerance_hz:
                result_code = 0
            elif self.dds_frequency_hz < target_hz:
                result_code = 1
            else:
                result_code = 2
            match_score = clamp_int(
                1000
                - int(
                    1000
                    * error_hz
                    / max(1, 4 * tolerance_hz)
                ),
                0,
                1000,
            )
            confidence = self.coarse_confidence

        payload = struct.pack(
            "<HHBHB",
            self.session_id,
            self.dds_test_id,
            result_code,
            match_score,
            clamp_int(confidence, 0, 100),
        )
        self._cache_and_send_result(TYPE_DDS_TEST_RESULT, payload)
        self.state = STATE_WAIT_DDS
        print(
            "【DDS联调结果】编号%d，结果%d，匹配%d/1000，可信度%d%%"
            % (
                self.dds_test_id,
                result_code,
                match_score,
                confidence,
            )
        )


try:
    boot_started = SCRIPT_STARTED_MS
except NameError:
    boot_started = ticks_ms()

print("")
print("【启动】Task5 双档识别 + UART7")
camera = setup_camera()
display = setup_display()
uart = setup_uart()
link = ProtocolLink(uart)
controller = Task5Controller(link)
clock = time.clock()
print(
    "【就绪】%dms；UART7 115200，P14发送/P13接收"
    % ticks_diff(ticks_ms(), boot_started)
)
print("【等待】请由F407发送 START_TASK")

while True:
    clock.tick()

    # Handle all available commands before any expensive image operation.
    controller.poll_uart()
    controller.prepare_classifier_if_needed()

    try:
        frame = camera.snapshot()
    except Exception as error:
        print("【相机错误】%s" % error)
        if controller.state == STATE_COARSE:
            controller.send_coarse_result(2, 0.0, 0)
        continue

    # A command arriving during snapshot is acknowledged before PCA work.
    controller.poll_uart()
    controller.process_coarse_frame(frame)
    controller.process_dds_if_due()
    controller.poll_uart()

    if display is not None:
        try:
            display.update_if_due(frame, now_ms=ticks_ms())
        except Exception as error:
            display.error_count += 1
            if display.error_count == 1 or (display.error_count % 10) == 0:
                print(
                    "【OLED错误】刷新失败%d次：%s"
                    % (display.error_count, error)
                )

    if IDE_STREAM_ENABLED:
        annotate(frame, controller, clock.fps())
